const c=require('crypto');
const expected='62923ccda3a8bcb86b9a446feb430b7a8aa40cfd6c7b87c960a327a8b9ef72ac';
const seps=['-','_',' ',''];
let found=[];
for (const a of seps) for (const b of seps) for (const pre of ['', '-','_']) for (const suf of ['', '-','_']) {
  const s=pre+'quarterly'+a+'report'+b+'2026'+suf;
  if (!s.includes('_2026')) continue;
  const h=c.createHash('sha256').update(s,'utf8').digest('hex');
  if (h===expected) found.push(s);
}
console.log('found',found);
